#!/bin/bash
set -e
f=payload_index.rs
perl -0pi -e 's/        let ids: Vec<String> = \(0\.\.5\)\n            \.map\(\|index\| \{\n                store\n                    \.ingest\(&format!\("request-\{index\}"\), "source", "log", format!\("line \{index\}\\n"\)\.as_bytes\(\), 10\)\n                    \.unwrap\(\)\n                    \.id\n            \}\)\n            \.collect\(\);\n/        for index in 0..5 {\n            store\n                .ingest(\n                    &format!("request-{index}"),\n                    "source",\n                    "log",\n                    format!("line {index}\\n").as_bytes(),\n                    10,\n                )\n                .unwrap();\n        }\n/' $f
perl -0pi -e 's/        let indexed = \|store: &Store\| -> usize \{\n            ids\.iter\(\)\n                \.map\(\|_\| 0\)\n                \.sum::<usize>\(\)\n                \+ \(0\.\.5\)\n                    \.map\(\|index\| \{\n                        let id = format!\(\n                            "blake3:\{\}",\n                            hex::encode\(blake3::hash\(format!\("line \{index\}\\n"\)\.as_bytes\(\)\)\.as_bytes\(\)\)\n                        \);\n                        store\.payload_lookup\(&id, None, 10\)\.unwrap\(\)\.artifacts\.len\(\)\n                    \}\)\n                    \.sum::<usize>\(\)\n        \};/        let indexed = |store: &Store| -> usize {\n            (0..5)\n                .map(|index| {\n                    let id = format!(\n                        "blake3:{}",\n                        hex::encode(blake3::hash(format!("line {index}\\n").as_bytes()).as_bytes())\n                    );\n                    store.payload_lookup(&id, None, 10).unwrap().artifacts.len()\n                })\n                .sum()\n        };/' $f
perl -0pi -e 's/        assert!\(!store\.payload_lookup\("blake3:"[^\n]*\n//' $f
